      "rawText": "首页 前新加坡外长：多亏中国，我们小国也能从AI中受益 曲乔乔 。 7月9日晚，新加坡前外交部长杨荣文在一场炉边对话会上表示，中国人工智能（AI）产业选择开源的关键决定，带动包括美国科企在内的大型企业也开始转向开源。 据新加坡《联合早报》10日报道，杨荣文称，中国选择开源是一件好事，其目的是推动AI迅速扩展到中国经济的各个领域，“像新加坡这样的小国也能从中受益”。 “开源意味着，即便是新加坡也可以采用开源模型，购买自己的服务，在不开放自身数据的情况下运用大模型，”他说，“我看到所有国家和越来越多企业正往同个方向走。” 9日晚，杨荣文（右）出席论坛谈AI和中国 联合早报 杨荣文同时指出，中美在AI领域的差距正在缩小。 他提到，有段时间，美国科技“七巨头”和美国政府都认为，美国在AI领域遥遥领先，主导地位将无休止地延续下去；后来，中国推出了深度求索（DeepSeek）。 “从那时起，中国看似落后于美国六个月、九个月，如今可能只落后三个月，”他继续表示，“当人们在图表上画出这两条线时，他们好奇中国何时会超越美国。目前，我们不知道，但在美国的人对此深感担忧。” 会上，他还反驳西方唱衰中国经济的",
